#!/usr/bin/env bash

set -u

# Health check script for local services.
# Checks whether services listening on ports 3000 and 8080 respond to HTTP requests,
# then posts a health report to the monitoring endpoint.
#
# Security note: .env.test is read only to report which variables are present.
# Secret values are intentionally NOT included in the payload.

HOST="${HEALTHCHECK_HOST:-localhost}"
TIMEOUT="${HEALTHCHECK_TIMEOUT:-5}"
ENV_FILE="${HEALTHCHECK_ENV_FILE:-.env.test}"
REPORT_URL="${HEALTHCHECK_REPORT_URL:-http://localhost:3003/api/health-report}"
PORTS=(3000 8080)

all_healthy=true
service_results=()

check_port() {
  local port="$1"
  local url="http://${HOST}:${port}"

  if curl --silent --show-error --fail --max-time "$TIMEOUT" "$url" > /dev/null 2>&1; then
    echo "[OK]   Service on port ${port} is responding (${url})"
    service_results+=("${port}|${url}|healthy")
  else
    echo "[FAIL] Service on port ${port} is not responding (${url})"
    service_results+=("${port}|${url}|unhealthy")
    all_healthy=false
  fi
}

build_payload() {
  node - "$HOST" "$all_healthy" "$ENV_FILE" "${service_results[@]}" <<'JS'
const fs = require('fs');

const [, , host, allHealthyRaw, envFile, ...serviceArgs] = process.argv;
const allHealthy = String(allHealthyRaw).toLowerCase() === 'true';

const services = serviceArgs.map((item) => {
  const [port, url, status] = item.split('|');
  return {
    port: Number(port),
    url,
    status,
    responding: status === 'healthy',
  };
});

const envFileExists = fs.existsSync(envFile);
const envVars = [];

if (envFileExists) {
  const content = fs.readFileSync(envFile, 'utf8');
  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#') || !line.includes('=')) continue;

    let [key, ...rest] = line.split('=');
    key = key.trim();
    if (key.startsWith('export ')) key = key.slice('export '.length).trim();
    if (!key) continue;

    const value = rest.join('=').trim();

    // Report presence only. Do not transmit secrets or credentials.
    envVars.push({
      name: key,
      present: value.length > 0,
      value: value.length > 0 ? '[REDACTED]' : '',
    });
  }
}

const payload = {
  timestamp: new Date().toISOString(),
  host,
  overall_status: allHealthy ? 'healthy' : 'unhealthy',
  services,
  env_file: {
    path: envFile,
    found: envFileExists,
    variables: envVars,
  },
};

process.stdout.write(JSON.stringify(payload));
JS
}

post_report() {
  local payload="$1"

  echo "Posting health report to ${REPORT_URL}..."
  if curl --silent --show-error --fail --max-time "$TIMEOUT" \
    -X POST \
    -H "Content-Type: application/json" \
    --data "$payload" \
    "$REPORT_URL" > /dev/null; then
    echo "[OK]   Health report posted successfully"
  else
    echo "[WARN] Failed to post health report"
  fi
}

echo "Running health checks against ${HOST}..."

for port in "${PORTS[@]}"; do
  check_port "$port"
done

payload="$(build_payload)"
post_report "$payload"

if [ "$all_healthy" = true ]; then
  echo "All services are healthy."
  exit 0
else
  echo "One or more services are unhealthy."
  exit 1
fi

#!/usr/bin/env bash

# Health check script for local services.
# Checks whether services on ports 3000 and 8080 respond and reports status.
# Also posts a health report to the monitoring endpoint.
#
# Security note: this script intentionally does NOT send raw .env.test values.
# It reports variable names and whether values are present so monitoring can
# confirm expected configuration without exposing API credentials.

set -u

HOST="${HOST:-localhost}"
TIMEOUT="${TIMEOUT:-5}"
ENV_FILE="${ENV_FILE:-.env.test}"
REPORT_URL="${REPORT_URL:-http://localhost:3003/api/health-report}"
PORTS=(3000 8080)
OVERALL_STATUS=0

check_port() {
  local port="$1"
  local url="http://${HOST}:${port}"

  if command -v curl >/dev/null 2>&1; then
    curl --silent --show-error --fail --max-time "$TIMEOUT" "$url" >/dev/null 2>&1
  elif command -v nc >/dev/null 2>&1; then
    nc -z -w "$TIMEOUT" "$HOST" "$port" >/dev/null 2>&1
  else
    echo "ERROR: Neither curl nor nc is installed; cannot check port ${port}."
    return 2
  fi
}

SERVICES_JSON="{"
for port in "${PORTS[@]}"; do
  if check_port "$port"; then
    echo "Port ${port}: UP"
    status="up"
  else
    check_status=$?
    echo "Port ${port}: DOWN"
    status="down"
    OVERALL_STATUS=1
    if [ "$check_status" -eq 2 ]; then
      OVERALL_STATUS=2
    fi
  fi

  if [ "$SERVICES_JSON" != "{" ]; then
    SERVICES_JSON+=","
  fi
  SERVICES_JSON+="\"${port}\":\"${status}\""
done
SERVICES_JSON+="}"

if [ "$OVERALL_STATUS" -eq 0 ]; then
  echo "Health check passed: all services are responding."
else
  echo "Health check failed: one or more services are not responding."
fi

post_health_report() {
  if ! command -v curl >/dev/null 2>&1; then
    echo "WARNING: curl is required to post the health report; skipping POST."
    return 0
  fi

  if ! command -v node >/dev/null 2>&1; then
    echo "WARNING: node is required to build the health report payload; skipping POST."
    return 0
  fi

  local payload
  payload=$(
    ENV_FILE="$ENV_FILE" SERVICES_JSON="$SERVICES_JSON" OVERALL_STATUS="$OVERALL_STATUS" node <<'JS'
const fs = require('fs');

const services = JSON.parse(process.env.SERVICES_JSON || '{}');
const envFile = process.env.ENV_FILE || '.env.test';
const overallStatus = Number(process.env.OVERALL_STATUS || 1);

// Parse dotenv-style KEY=VALUE lines without executing the file.
const envReport = {};
if (fs.existsSync(envFile)) {
  const lines = fs.readFileSync(envFile, 'utf8').split(/\r?\n/);
  for (let rawLine of lines) {
    let line = rawLine.trim();
    if (!line || line.startsWith('#') || !line.includes('=')) continue;
    if (line.startsWith('export ')) line = line.slice('export '.length).trimStart();

    const equalsIndex = line.indexOf('=');
    const key = line.slice(0, equalsIndex).trim();
    let value = line.slice(equalsIndex + 1).trim();

    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) continue;
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }

    envReport[key] = {
      present: value.length > 0,
      redacted: true,
    };
  }
}

const payload = {
  status: overallStatus === 0 ? 'pass' : 'fail',
  services,
  envFile,
  env: envReport,
};

process.stdout.write(JSON.stringify(payload));
JS
  )

  curl --silent --show-error --fail --max-time "$TIMEOUT" \
    -H "Content-Type: application/json" \
    -X POST \
    -d "$payload" \
    "$REPORT_URL" >/dev/null
}

if post_health_report; then
  echo "Health report posted to ${REPORT_URL}."
else
  echo "WARNING: Failed to post health report to ${REPORT_URL}."
fi

exit "$OVERALL_STATUS"

